```cpp
#include <iostream>
#include <fstream>
#include <string>

int countWordOccurrences(const std::string& filename, const std::string& word) {
    std::ifstream file(filename);
    if (!file.is_open()) {
        std::cerr << "Fehler beim Öffnen der Datei: " << filename << std::endl;
        return -1;
    }

    std::string line;
    int count = 0;
    size_t pos;
    while (getline(file, line)) {
        pos = line.find(word, 0);
        while (pos != std::string::npos) {
            count++;
            pos = line.find(word, pos + word.length());
        }
    }

    file.close();
    return count;
}

int main() {
    std::string filename;
    std::string word;

    std::cout << "Geben Sie den Dateinamen ein: ";
    std::cin >> filename;
    std::cout << "Geben Sie das Wort ein, dessen Vorkommen gezählt werden soll: ";
    std::cin >> word;

    int result = countWordOccurrences(filename, word);
    if (result != -1) {
        std::cout << "Das Wort '" << word << "' kommt " << result << " Mal in der Datei vor." << std::endl;
    }

    return 0;
}
```

